package com.universalplatform.content;
import com.universalplatform.storage.*; import java.time.*; import java.util.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component class ContentRetentionWorker {
 private final LearningResourceRepository resources;private final LearningResourceVersionRepository versions;private final StorageObjectRepository objects;private final ContentRetentionPolicyRepository policies;private final StorageAdapterRegistry adapters;private final Clock clock=Clock.systemUTC();
 ContentRetentionWorker(LearningResourceRepository r,LearningResourceVersionRepository v,StorageObjectRepository o,ContentRetentionPolicyRepository p,StorageAdapterRegistry a){resources=r;versions=v;objects=o;policies=p;adapters=a;}
 @Scheduled(fixedDelayString="${platform.storage.retention-poll-ms:3600000}") @Transactional void purgeExpired(){Instant now=clock.instant();for(LearningResource r:resources.findTop100ByExpiresAtBeforeOrderByExpiresAtAsc(now)){ContentRetentionPolicy policy=policies.findById(r.tenantId).orElse(null);int grace=policy==null?30:policy.deletedObjectGraceDays;if(r.expiresAt.plus(Duration.ofDays(grace)).isAfter(now))continue;for(LearningResourceVersion v:versions.findAllByTenantIdAndResourceIdOrderByVersionNumberDesc(r.tenantId,r.id)){if(v.storageObjectId==null)continue;StorageObject o=objects.findByTenantIdAndId(r.tenantId,v.storageObjectId).orElse(null);if(o==null||o.status==StorageObjectStatus.DELETED)continue;try{adapters.require(o.provider).delete(o.locator);o.markDeleted(now);}catch(Exception ignored){/* retry on next poll; provider errors must not corrupt metadata */}}}}
}
